# --- THIS IS A SCRIPT GENERATED BY CHATGPT ---
#!/usr/bin/env bash
set -euo pipefail

# bench_split_genesis.sh
# Measure how long it takes to *build* (and optionally sign/submit) a single "split genesis" transaction
# that fans out the genesis UTxO into N outputs, for N in a range (default: 2..400).
#
# By default this runs in DRY_RUN mode (build only, does not sign/submit), so you can reuse the same UTxO
# for all N without consuming it. If you set DRY_RUN=0, the script will sign & submit transactions, which
# will consume your input UTxO on the first iteration (subsequent iterations will fail unless you reset).
#
# USAGE:
#   chmod +x bench_split_genesis.sh
#   ./bench_split_genesis.sh 2 400
#
# Optional env vars:
#   TESTNET_MAGIC=42
#   STATE_DIR="/home/ubuntu/cardano/cardano-node-tests/dev_workdir/state-cluster0"
#   DESTINATION_ADDR="$STATE_DIR/nodes/node-pool1/owner.addr"
#   GENESIS_ADDR="$STATE_DIR/shelley/genesis-utxo.addr"
#   SIGNING_KEY="$STATE_DIR/shelley/genesis-utxo.skey"
#   CARDANO_NODE_SOCKET_PATH="$PWD/dev_workdir/state-cluster0/bft1.socket"
#   DRY_RUN=1        # 1=build only; 0=build+sign+submit (consumes UTxO)
#   OUTPUT_AMOUNT=2000000   # per-output ADA in lovelace; must be >= min UTxO on your network
#   CSV_OUT="split_bench.csv"
#
# Output: a CSV with columns:
#   n_outputs,status,build_ms,sign_ms,submit_ms,txbody_bytes,fee_lovelace,error
#
# Notes:
# - If build fails (e.g., exceeds max tx size or min UTxO), the error is logged in the CSV.
# - In DRY_RUN=1, we still compute txbody size and estimated fee from the build step.
# - You can switch DESTINATION_ADDR to a round-robin across multiple pool owner addrs if desired.

TESTNET_MAGIC="${TESTNET_MAGIC:-42}"
STATE_DIR="${STATE_DIR:-/home/ubuntu/cardano/cardano-node-tests/dev_workdir/state-cluster0}"
GENESIS_ADDR_FILE="${GENESIS_ADDR:-$STATE_DIR/shelley/genesis-utxo.addr}"
DESTINATION_ADDR_FILE="${DESTINATION_ADDR:-$STATE_DIR/nodes/node-pool1/owner.addr}"
SIGNING_KEY="${SIGNING_KEY:-$STATE_DIR/shelley/genesis-utxo.skey}"
CSV_OUT="${CSV_OUT:-split_bench.csv}"
DRY_RUN="${DRY_RUN:-1}"
OUTPUT_AMOUNT="${OUTPUT_AMOUNT:-2000000}"

# sanity checks
if [[ ! -f "$GENESIS_ADDR_FILE" ]]; then
  echo "Missing GENESIS_ADDR file: $GENESIS_ADDR_FILE" >&2; exit 1
fi
if [[ ! -f "$DESTINATION_ADDR_FILE" ]]; then
  echo "Missing DESTINATION_ADDR file: $DESTINATION_ADDR_FILE" >&2; exit 1
fi
if [[ "$DRY_RUN" != "0" && "$DRY_RUN" != "1" ]]; then
  echo "DRY_RUN must be 0 or 1"; exit 1
fi

GENESIS_ADDR=$(cat "$GENESIS_ADDR_FILE")
DESTINATION_ADDR=$(cat "$DESTINATION_ADDR_FILE")

if [[ -z "${CARDANO_NODE_SOCKET_PATH:-}" ]]; then
  echo "CARDANO_NODE_SOCKET_PATH is not set; export it before running." >&2
  exit 1
fi

if [[ $# -lt 2 ]]; then
  echo "Usage: $0 <min_n_outputs> <max_n_outputs>" >&2
  exit 1
fi

MIN_N="$1"
MAX_N="$2"

# temp working dir
WORKDIR="$(mktemp -d -t splitbench-XXXXXX)"
trap 'rm -rf "$WORKDIR"' EXIT

echo "Writing results to $CSV_OUT"
echo "n_outputs,status,build_ms,sign_ms,submit_ms,txbody_bytes,fee_lovelace,error" > "$CSV_OUT"

# locate current genesis UTxO (hash and index); expects a single line entry for the genesis address
UTXO_LINE=$(cardano-cli conway query utxo --address "$GENESIS_ADDR" --testnet-magic "$TESTNET_MAGIC" | awk 'NR==3')
if [[ -z "$UTXO_LINE" ]]; then
  echo "Could not find a UTxO at the genesis address ($GENESIS_ADDR). Is the cluster running?" >&2
  exit 1
fi
TX_HASH=$(echo "$UTXO_LINE" | awk '{print $1}')
TX_IX=$(echo "$UTXO_LINE" | awk '{print $2}')

echo "Using genesis UTxO: ${TX_HASH}#${TX_IX}"

# helper: millis since epoch
millis() { date +%s%3N; }

for (( N=MIN_N; N<=MAX_N; N++ )); do
  BUILD_START=$(millis)
  TXBODY="$WORKDIR/tx_${N}.txbody"
  TXSIGNED="$WORKDIR/tx_${N}.signed"
  ERR_FILE="$WORKDIR/err_${N}.log"
  FEE_FILE="$WORKDIR/fee_${N}.log"

  # construct repeated --tx-out args
  OUT_ARGS=()
  for (( i=0; i<N; i++ )); do
    OUT_ARGS+=( --tx-out "${DESTINATION_ADDR}+${OUTPUT_AMOUNT}" )
  done

  # Build (auto fee, change back to genesis)
  set +e
  BUILD_OUT=$(cardano-cli conway transaction build \
    --tx-in "${TX_HASH}#${TX_IX}" \
    "${OUT_ARGS[@]}" \
    --change-address "$GENESIS_ADDR" \
    --testnet-magic "$TESTNET_MAGIC" \
    --out-file "$TXBODY" 2> "$ERR_FILE")
  BUILD_RC=$?
  set -e

  BUILD_END=$(millis)
  BUILD_MS=$(( BUILD_END - BUILD_START ))
  SIGN_MS=""
  SUBMIT_MS=""
  TXBYTES=""
  FEE=""

  if [[ "$BUILD_RC" -ne 0 ]]; then
    # Capture error message (first line)
    ERR_MSG=$(head -n 1 "$ERR_FILE" | tr ',' ';' | tr -d '\r\n')
    echo "${N},build_failed,${BUILD_MS},,,,$(echo -n "$ERR_MSG" | tr -d '\n')" >> "$CSV_OUT"
    echo "N=${N}: build_failed (${ERR_MSG})"
    continue
  fi

  # file size (bytes)
  if [[ -f "$TXBODY" ]]; then
    TXBYTES=$(stat -c%s "$TXBODY" 2>/dev/null || echo "")
  fi

  # Try to parse estimated fee from build output (line like: 'Estimated transaction fee: 171485 Lovelace')
  if echo "$BUILD_OUT" | grep -qi 'Estimated transaction fee'; then
    FEE=$(echo "$BUILD_OUT" | awk '/Estimated transaction fee/ {print $5}')
  else
    # Sometimes build prints to stderr; try there
    if grep -qi 'Estimated transaction fee' "$ERR_FILE"; then
      FEE=$(awk '/Estimated transaction fee/ {print $5}' "$ERR_FILE")
    fi
  fi

  if [[ "$DRY_RUN" -eq 1 ]]; then
    echo "${N},built,${BUILD_MS},,,${TXBYTES},${FEE}," >> "$CSV_OUT"
    echo "N=${N}: built (txbody=${TXBYTES} bytes, fee=${FEE})"
    continue
  fi

  # Sign
  SIGN_START=$(millis)
  cardano-cli conway transaction sign \
    --signing-key-file "$SIGNING_KEY" \
    --testnet-magic "$TESTNET_MAGIC" \
    --tx-body-file "$TXBODY" \
    --out-file "$TXSIGNED"
  SIGN_END=$(millis)
  SIGN_MS=$(( SIGN_END - SIGN_START ))

  # Submit
  set +e
  SUBMIT_START=$(millis)
  SUBMIT_OUT=$(cardano-cli conway transaction submit --tx-file "$TXSIGNED" --testnet-magic "$TESTNET_MAGIC" 2>> "$ERR_FILE")
  SUBMIT_RC=$?
  SUBMIT_END=$(millis)
  set -e
  SUBMIT_MS=$(( SUBMIT_END - SUBMIT_START ))

  if [[ "$SUBMIT_RC" -ne 0 ]]; then
    ERR_MSG=$(tail -n 1 "$ERR_FILE" | tr ',' ';' | tr -d '\r\n')
    echo "${N},submit_failed,${BUILD_MS},${SIGN_MS},${SUBMIT_MS},${TXBYTES},${FEE},$(echo -n "$ERR_MSG" | tr -d '\n')" >> "$CSV_OUT"
    echo "N=${N}: submit_failed (${ERR_MSG})"
    continue
  fi

  echo "${N},submitted,${BUILD_MS},${SIGN_MS},${SUBMIT_MS},${TXBYTES},${FEE}," >> "$CSV_OUT"
  echo "N=${N}: submitted (txbody=${TXBYTES} bytes, fee=${FEE})"

  # IMPORTANT: After first successful submit, the original UTxO is consumed.
  # Subsequent iterations will likely fail unless you intentionally stop after one.
  # This is why DRY_RUN=1 is recommended for benchmarking build times across many N.
done

echo "Done. Results saved to: $CSV_OUT"
